"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["76939"],{74638(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.regra_derivacao_configurada.ordem_invalida","status":422,"titulo":"A ordem da regra n\xe3o pode ser negativa"},"descricao":{"codigo":"uniplus.selecao.regra_derivacao_configurada.ordem_invalida","requisitos":[],"oQueAconteceu":["Na defini\xe7\xe3o das regras de deriva\xe7\xe3o do processo\\n(`PUT /api/selecao/processos-seletivos/{id}/regras-derivacao`), uma regra\\ninformou `ordem` menor que zero. A ordem posiciona a regra na configura\xe7\xe3o do\\nfato derivado e \xe9 um n\xfamero inteiro a partir de zero.","A recusa vem no array `errors[]`, no campo\\n`configuracoes[<i>].regras[<j>].ordem`, e faz parte da confer\xeancia de forma, que\\nacumula todas as viola\xe7\xf5es de todas as configura\xe7\xf5es e regras do pedido antes de\\nconsultar o cat\xe1logo de fatos. Ela acumula, por exemplo, com a ordem repetida\\n([`ordem_regra_duplicada`](/erros/uniplus.selecao.configuracao_derivacao_fato.ordem_regra_duplicada)).","A mesma confer\xeancia roda quando o sistema rel\xea a configura\xe7\xe3o congelada da\\nvers\xe3o publicada, nas demais opera\xe7\xf5es da lista do cabe\xe7alho. A consulta de\\nconformidade do processo tamb\xe9m rel\xea a vers\xe3o, mas converte a falha em pend\xeancia\\ndo checklist, e por isso n\xe3o consta no cabe\xe7alho. Pelo caminho normal de\\ngrava\xe7\xe3o, a configura\xe7\xe3o congelada nunca traz uma ordem negativa, porque a\\ndefini\xe7\xe3o das regras a recusa antes. Nessas leituras a recusa sai como viola\xe7\xe3o\\n\xfanica, sem a lista `errors[]`, e se refere \xe0 vers\xe3o congelada, n\xe3o ao pedido\\nenviado."],"comoResolver":["Na defini\xe7\xe3o das regras, d\xea a cada regra uma `ordem` igual ou maior que zero e\\n\xfanica dentro da configura\xe7\xe3o do fato, e envie o pedido de novo.","Se o erro apareceu em uma opera\xe7\xe3o que l\xea a configura\xe7\xe3o congelada (qualquer\\numa das listadas no cabe\xe7alho, exceto a defini\xe7\xe3o das regras), o pedido enviado\\nagora n\xe3o \xe9 a causa: o defeito est\xe1 na regra de deriva\xe7\xe3o congelada na vers\xe3o\\npublicada do processo, e regravar as regras do processo n\xe3o a corrige. A causa \xe9\\ninvestigada pela equipe t\xe9cnica do Uni+."],"ondeAparece":["Defini\xe7\xe3o de regras de deriva\xe7\xe3o de fatos do processo seletivo","Retifica\xe7\xe3o em ato \xfanico","Apresenta\xe7\xe3o do formul\xe1rio do processo","Consulta do formul\xe1rio da inscri\xe7\xe3o","In\xedcio, salvamento, envio, cancelamento e descarte do rascunho da inscri\xe7\xe3o","Avalia\xe7\xe3o da inscri\xe7\xe3o","In\xedcio, confirma\xe7\xe3o e remo\xe7\xe3o de envio de documento da inscri\xe7\xe3o","Consulta e emiss\xe3o do comprovante da inscri\xe7\xe3o","Consulta administrativa da inscri\xe7\xe3o e dos documentos dela","Publica\xe7\xe3o de produto do edital e listagem de produtos previstos do processo","Notas do ENEM (importa\xe7\xe3o de lote, gera\xe7\xe3o do envio ao INEP e consulta de lotes e de envios)"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Regra derivacao configurada"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"d146f1ba7c5762ff6b06be66801aa6e88c9be916"}}')}}]);